SELECT COALESCE(r.i_item_sk,       r.old__i_item_sk)::text          AS id,
       COALESCE(r.i_item_id,       r.old__i_item_id,       '')   AS item_id,
       COALESCE(r.i_rec_start_date,r.old__i_rec_start_date,'1900-01-01'::date) AS rec_start_date,
       COALESCE(r.i_rec_end_date,  r.old__i_rec_end_date,  '9999-12-31'::date) AS rec_end_date,
       COALESCE(r.i_item_desc,     r.old__i_item_desc,     '')   AS item_desc,
       COALESCE(r.i_current_price, r.old__i_current_price, 0.0)::float8 AS current_price,
       COALESCE(r.i_wholesale_cost,r.old__i_wholesale_cost,0.0)::float8 AS wholesale_cost,
       COALESCE(r.i_brand_id,      r.old__i_brand_id,      0)    AS brand_id,
       COALESCE(r.i_brand,         r.old__i_brand,         '')   AS brand,
       COALESCE(r.i_class_id,      r.old__i_class_id,      0)    AS class_id,
       COALESCE(r.i_class,         r.old__i_class,         '')   AS i_class,
       COALESCE(r.i_category_id,   r.old__i_category_id,   0)    AS category_id,
       COALESCE(r.i_category,      r.old__i_category,      '')   AS category,
       COALESCE(r.i_manufact_id,   r.old__i_manufact_id,   0)    AS manufact_id,
       COALESCE(r.i_manufact,      r.old__i_manufact,      '')   AS manufact,
       COALESCE(r.i_size,          r.old__i_size,          '')   AS i_size,
       COALESCE(r.i_formulation,   r.old__i_formulation,   '')   AS formulation,
       COALESCE(r.i_color,         r.old__i_color,         '')   AS color,
       COALESCE(r.i_units,         r.old__i_units,         '')   AS units,
       COALESCE(r.i_container,     r.old__i_container,     '')   AS container,
       COALESCE(r.i_manager_id,    r.old__i_manager_id,    0)    AS manager_id,
       COALESCE(r.i_product_name,  r.old__i_product_name,  '')   AS product_name
FROM {{ .rows }}
